import{_ as e,o as t,c as i,a4 as o}from"./chunks/framework.BRzJ4ijD.js";const m=JSON.parse('{"title":"Dynamo Family: Cassandra / Riak / DynamoDB","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/case/dynamo-family.md","filePath":"system-design/case/dynamo-family.md","lastUpdated":1788475713000}'),n={name:"system-design/case/dynamo-family.md"};function s(r,a,l,d,c,h){return t(),i("div",null,[...a[0]||(a[0]=[o(`<h1 id="dynamo-family-cassandra-riak-dynamodb" tabindex="-1">Dynamo Family: Cassandra / Riak / DynamoDB <a class="header-anchor" href="#dynamo-family-cassandra-riak-dynamodb" aria-label="Permalink to &quot;Dynamo Family: Cassandra / Riak / DynamoDB&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Amazon Dynamo (2007 SOSP) 论文是 AP 键值系统的 圣经——<strong>永远可写, 最终一致, 让服务 (shopping cart) 总可用</strong>。 Cassandra / Riak / Voldemort / DynamoDB 是 Dynamo 概念的 工业 实现。Cassandra 成为 Facebook → Apache 的 分布式 wide-column store; Riak 由 Basho 设计为 eventually-consistent Dynamo-style with CRDT; DynamoDB 是 AWS managed 版本, 带 optional strong consistency。本章分析 Dynamo paper 核心: consistent hashing + virtual nodes + hinted handoff + anti-entropy + sloppy quorum + vector clock — 以及它们如何演化到 Cassandra 与其他派生。</p><hr><h2 id="一、dynamo-纸核心架构-2007" tabindex="-1">一、Dynamo 纸核心架构 (2007) <a class="header-anchor" href="#一、dynamo-纸核心架构-2007" aria-label="Permalink to &quot;一、Dynamo 纸核心架构 (2007)&quot;">​</a></h2><h3 id="前提-总是可写-ap" tabindex="-1">前提: &quot;总是可写&quot; (AP) <a class="header-anchor" href="#前提-总是可写-ap" aria-label="Permalink to &quot;前提: &quot;总是可写&quot; (AP)&quot;">​</a></h3><p>一个 Amazon shopping cart 必须<strong>always add item</strong> 即便部分节点 down。 不能 block write =&gt; availability pick over consistency。 网络分区 持续 仍写 =&gt; AP system。</p><h3 id="consistent-hashing" tabindex="-1">Consistent Hashing <a class="header-anchor" href="#consistent-hashing" aria-label="Permalink to &quot;Consistent Hashing&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>key hash(key) → position in ring [0, 2^160-1]</span></span>
<span class="line"><span>每个 node 分配 N 个 virtual positions (vnodes)</span></span>
<span class="line"><span>写入 N 个 replicas walking clockwise.</span></span></code></pre></div><p>每个 key 的 replication set = 首 node + next (N-1) clockwise nodes。</p><h3 id="sloppy-quorum" tabindex="-1">Sloppy Quorum <a class="header-anchor" href="#sloppy-quorum" aria-label="Permalink to &quot;Sloppy Quorum&quot;">​</a></h3><p>若 preferred N 节点部分 down, Dynamo 选次邻 node (no strict ring)。 保证 write 完成; use hinted handoff 暂存本地, 转给 real owner after recovery。</p><h3 id="w-r-n-consistency-levels" tabindex="-1">W, R, N Consistency Levels <a class="header-anchor" href="#w-r-n-consistency-levels" aria-label="Permalink to &quot;W, R, N Consistency Levels&quot;">​</a></h3><ul><li>N=3 (replication factor)</li><li>client configurable W (write quorum), R (read quorum)</li><li>W+R &gt; N for quorum overlap =&gt; stale-proof</li></ul><p>案例: Amazon&#39;s shopping cart: N=3, R=1, W=1 (快速, 但可能 stale)</p><h3 id="vector-clock-sibling" tabindex="-1">Vector Clock + Sibling <a class="header-anchor" href="#vector-clock-sibling" aria-label="Permalink to &quot;Vector Clock + Sibling&quot;">​</a></h3><p>Each version of data has vector clock [[node:counter]] from last update. Coordinator see sibling when vector clock incomparable → return all client for resolution (e.g., shopping cart merge by application)</p><h3 id="hinted-handoff" tabindex="-1">Hinted Handoff <a class="header-anchor" href="#hinted-handoff" aria-label="Permalink to &quot;Hinted Handoff&quot;">​</a></h3><p>当 write target replica unavailable, coordinator store hint (包括 key+value) locally。 节点回来后 push hint =&gt; data.</p><h3 id="anti-entropy-with-merkle-tree" tabindex="-1">Anti-Entropy with Merkle Tree <a class="header-anchor" href="#anti-entropy-with-merkle-tree" aria-label="Permalink to &quot;Anti-Entropy with Merkle Tree&quot;">​</a></h3><p>Background 比较 副本 differ range 推 specific missing keys。 Merkle Tree lazy periodic sync, ensure cold keys converge。</p><h3 id="gossip-protocol" tabindex="-1">Gossip Protocol <a class="header-anchor" href="#gossip-protocol" aria-label="Permalink to &quot;Gossip Protocol&quot;">​</a></h3><p>Cluster membership via random peer gossip (no 集中 config server). 每个节点 每 1s 跟 random peer exchange membership info。</p><hr><h2 id="二、cassandra-facebook-2008-→-apache" tabindex="-1">二、Cassandra (Facebook 2008 → Apache) <a class="header-anchor" href="#二、cassandra-facebook-2008-→-apache" aria-label="Permalink to &quot;二、Cassandra (Facebook 2008 → Apache)&quot;">​</a></h2><h3 id="混合-dynamo-bigtable" tabindex="-1">混合 Dynamo + BigTable <a class="header-anchor" href="#混合-dynamo-bigtable" aria-label="Permalink to &quot;混合 Dynamo + BigTable&quot;">​</a></h3><p>Cassandra 在 Dynamo&#39;s partition + replication model 上 加 BigTable 列模型。</p><p>每 table = partition key + clustering columns:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> user_activity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    user_id UUID,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    timestamp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TIMESTAMP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    event</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TEXT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (user_id, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">timestamp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>每 partition 内 (secondary key) 多个 row, 语义类似 sparse wide-row.</p><h3 id="gossip-hinted-handoff-read-repair-anti-entropy-—-all-inherited-from-dynamo" tabindex="-1">Gossip, hinted handoff, read repair, anti-entropy — all inherited from Dynamo <a class="header-anchor" href="#gossip-hinted-handoff-read-repair-anti-entropy-—-all-inherited-from-dynamo" aria-label="Permalink to &quot;Gossip, hinted handoff, read repair, anti-entropy — all inherited from Dynamo&quot;">​</a></h3><p>Cassandra adds:</p><ul><li><strong>Thrift/Native CQL protocol</strong> (not Dynamo simple interface)</li><li><strong>Tunable consistency (LOCAL_ONE / LOCAL_QUORUM / EACH_QUOURM)</strong></li><li><strong>SSTable + compaction (stcs / lcs / twcs)</strong></li><li><strong>Lightweight transactions (LWT via Paxos)</strong></li></ul><h3 id="implementation-differences" tabindex="-1">Implementation differences <a class="header-anchor" href="#implementation-differences" aria-label="Permalink to &quot;Implementation differences&quot;">​</a></h3><ul><li>Virtual nodes (vnodes) default 256 per node, ring mapping load balance auto.</li><li>LSM-tree: memtable + commitlog flush to SSTable → compaction merge.</li><li>Token-aware driver: clients aware of partition mapping reduce extra hop to coordinator.</li></ul><h3 id="scaling" tabindex="-1">Scaling <a class="header-anchor" href="#scaling" aria-label="Permalink to &quot;Scaling&quot;">​</a></h3><ul><li>Linearly scalable writes by adding nodes; data re-distribute via vnodes migration (move half token ranges).</li></ul><hr><h2 id="三、riak-basho-2009" tabindex="-1">三、Riak (Basho 2009) <a class="header-anchor" href="#三、riak-basho-2009" aria-label="Permalink to &quot;三、Riak (Basho 2009)&quot;">​</a></h2><h3 id="pure-dynamo" tabindex="-1">Pure Dynamo <a class="header-anchor" href="#pure-dynamo" aria-label="Permalink to &quot;Pure Dynamo&quot;">​</a></h3><p>Riak close follow Dynamo paper:</p><ul><li><code>consistent hashing (ring)</code> 配 vnodes (default 64);</li><li><strong>Sloppy quorum + hinted handoff</strong></li><li>vector clock sibling return <code>allow_mult=true</code></li><li>anti-entropy (active AAE background Merkle Tree sync)</li><li>gossip membership</li></ul><h3 id="data-types-crdt-since-riak-2-0" tabindex="-1">Data Types (CRDT since Riak 2.0) <a class="header-anchor" href="#data-types-crdt-since-riak-2-0" aria-label="Permalink to &quot;Data Types (CRDT since Riak 2.0)&quot;">​</a></h3><p>Riak DT: counters, sets, maps, flags (Conflict-free). 免 application merge by making data type converge according to CRDT.</p><h3 id="trade-offs" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h3><ul><li>No SQL query model; KV with bucket type CRDT; rich map/reduce-based query (JSON)</li><li>Eventual consistency / strong via <code>R=quorum</code></li></ul><h3 id="现状态" tabindex="-1">现状态 <a class="header-anchor" href="#现状态" aria-label="Permalink to &quot;现状态&quot;">​</a></h3><p>Basho shut down 2017 (company gone), Riak open source 停 更新 但 派生 项目 继续: Riak KV (Bet365 financial use).</p><hr><h2 id="四、dynamodb-aws-2012" tabindex="-1">四、DynamoDB (AWS, 2012) <a class="header-anchor" href="#四、dynamodb-aws-2012" aria-label="Permalink to &quot;四、DynamoDB (AWS, 2012)&quot;">​</a></h2><h3 id="managed-dynamo" tabindex="-1">Managed Dynamo <a class="header-anchor" href="#managed-dynamo" aria-label="Permalink to &quot;Managed Dynamo&quot;">​</a></h3><ul><li>Full managed (no operations like Cassandra)</li><li>API: <code>GetItem, PutItem, DeleteItem, Query, Scan</code></li><li>tables: partition key + optional sort key; 无 列模型; each item max 400KB</li><li>capacity mode: on-demand or provisioned (RCU/WCU)</li></ul><h3 id="read-consistency" tabindex="-1">Read consistency <a class="header-anchor" href="#read-consistency" aria-label="Permalink to &quot;Read consistency&quot;">​</a></h3><ul><li>Eventually Consistent Read (default): 可能 stale; P99 &lt; 10ms</li><li>Strongly Consistent Read: R=⌈N/2⌉+1 读 quorum; P99 &lt; 20ms; return most recent commit</li></ul><h3 id="global-table" tabindex="-1">Global Table <a class="header-anchor" href="#global-table" aria-label="Permalink to &quot;Global Table&quot;">​</a></h3><p>Multi-region active-active; write any region, async 复制 → eventual convergence + regional durable</p><h3 id="dynamodb-streams-dax-cache" tabindex="-1">DynamoDB Streams / DAX cache <a class="header-anchor" href="#dynamodb-streams-dax-cache" aria-label="Permalink to &quot;DynamoDB Streams / DAX cache&quot;">​</a></h3><ul><li>DynamoDB Streams: CDC for change events (KCL lambda trigger)</li><li>DAX: in-memory accelerator cluster 缓 读</li></ul><h3 id="comparison-with-cassandra" tabindex="-1">Comparison with Cassandra <a class="header-anchor" href="#comparison-with-cassandra" aria-label="Permalink to &quot;Comparison with Cassandra&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Cassandra</th><th>DynamoDB</th></tr></thead><tbody><tr><td>Hosting</td><td>self-managed / DataStax</td><td>AWS managed</td></tr><tr><td>Data model</td><td>rich wide-column + CQL</td><td>简单 PK+SK</td></tr><tr><td>Write throughput</td><td>lin scalable nodes, more hardware</td><td>auto scale RW capacity w/ 升</td></tr><tr><td>Data size limit</td><td>100TB+ per node possible</td><td>400KB per item max</td></tr><tr><td>Transactions</td><td>LWT (Paxos)</td><td>DynamoDB Transactions (serializable with 2PC)</td></tr><tr><td>Global Table</td><td>multi-DC replicas</td><td>global table replicas automatic</td></tr></tbody></table><hr><h2 id="五、dynamo-家族对比总结" tabindex="-1">五、Dynamo 家族对比总结 <a class="header-anchor" href="#五、dynamo-家族对比总结" aria-label="Permalink to &quot;五、Dynamo 家族对比总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>系统</th><th>年份</th><th>语言</th><th>数据模型</th><th>特色</th></tr></thead><tbody><tr><td>Amazon Dynamo (Paper)</td><td>2007</td><td>Java (internal)</td><td>simple KV</td><td>origin, trade-off AP focused</td></tr><tr><td>Cassandra</td><td>2008</td><td>Java</td><td>wide-column + CQL</td><td>BigTable model + Dynamo replication</td></tr><tr><td>Riak</td><td>2009</td><td>Erlang</td><td>KV + CRDT</td><td>CRDT native, ring成员 gossip</td></tr><tr><td>Voldemort</td><td>2009</td><td>Java</td><td>simple KV</td><td>LinkedIn rethought Dynamo + simple API</td></tr><tr><td>DynamoDB</td><td>2012</td><td>managed</td><td>简单 (PK/SK)</td><td>managed, strongly consistent read + DAX</td></tr></tbody></table><hr><h2 id="六、典型事故与教训" tabindex="-1">六、典型事故与教训 <a class="header-anchor" href="#六、典型事故与教训" aria-label="Permalink to &quot;六、典型事故与教训&quot;">​</a></h2><h3 id="cassandra-ttl-tombstone-explosion" tabindex="-1">Cassandra TTL + tombstone explosion <a class="header-anchor" href="#cassandra-ttl-tombstone-explosion" aria-label="Permalink to &quot;Cassandra  TTL + tombstone explosion&quot;">​</a></h3><p>Cassandra 2.x 默认 TTL 了 <strong>大量</strong> 过期数据 + tombstones 保留 <code>gc_grace_seconds</code> 默认 10 days, create read 需要 scan tombstones 让查询 慢 10x。 Solution: 修 compaction strategy TWCS + 缩短 gc_grace</p><h3 id="riak-node-flapping" tabindex="-1">Riak node flapping <a class="header-anchor" href="#riak-node-flapping" aria-label="Permalink to &quot;Riak node flapping&quot;">​</a></h3><p>Riak&#39;s gossip 处理 降 重 多 次 rejoin ring 当 node flapping, 导致 多 次 handoff storm. 修: Riak <code>ring_creation_size</code> 调 small + pre-join delay.</p><h3 id="dynamodb-rcu-wcu-burst-mode-exploiting" tabindex="-1">DynamoDB RCU/WCU burst mode exploiting <a class="header-anchor" href="#dynamodb-rcu-wcu-burst-mode-exploiting" aria-label="Permalink to &quot;DynamoDB RCU/WCU burst mode exploiting&quot;">​</a></h3><p>User 持续 writing H/RW mode 大量 short-burst capacity &gt; provisioned. 短暂 burst 允许, 但 sustained → throttling (ProvisionedThroughputExceededException). Solution: on-demand mode 或 autoscaling to absorb spikes.</p><h3 id="cassandra-lwt-overwhelm" tabindex="-1">Cassandra LWT overwhelm <a class="header-anchor" href="#cassandra-lwt-overwhelm" aria-label="Permalink to &quot;Cassandra LWT overwhelm&quot;">​</a></h3><p>某 Cassandra cluster 过度使 LWT (Paxos based Conditional Updates), LWT 4 RTT latency 占 80% 的 QPS cause P99 高度 slow. Solution: redesign use conflict-free CRDT or Redis lock instead.</p><h3 id="dynamodb-global-table-conflict" tabindex="-1">DynamoDB Global Table conflict <a class="header-anchor" href="#dynamodb-global-table-conflict" aria-label="Permalink to &quot;DynamoDB Global Table conflict&quot;">​</a></h3><p>Multi-region write 同时 same key, 后到达 version 用 LWW timestamp overwrite earlier. 某 系统 在 高 并发 下 丢 更新。 Solution: vector clock or merge function on application end.</p><hr><h2 id="七、易错清单" tabindex="-1">七、易错清单 <a class="header-anchor" href="#七、易错清单" aria-label="Permalink to &quot;七、易错清单&quot;">​</a></h2><ol><li><strong>Dynamo-style: never guarantee strong consistency without <code>W+R&gt;N</code> + read repair 反复 staleness</strong>.</li><li><strong>Cassandra LWT != scalable</strong>: Paxos 最高 throughput ~1K/s, not for hot path.</li><li><strong>GC_grace_seconds must set &lt; TTL expire</strong>: 否则 tombstone 聚; must 缩短 window.</li><li><strong>Sloppy quorum can violate W+R&gt;N shortcut</strong>: 当 consistent 需要, must enforce strict quorum (non-sloppy).</li><li><strong>DynamoDB transactions cost 2x more latency</strong>: simple reads prefer eventually.</li></ol><hr><h2 id="八、这一章带走的东西" tabindex="-1">八、这一章带走的东西 <a class="header-anchor" href="#八、这一章带走的东西" aria-label="Permalink to &quot;八、这一章带走的东西&quot;">​</a></h2><ol><li>Dynamo (2007) = AP leaderless ring + consistent hashing + vnodes + vector clock + hinted handoff.</li><li>Cassandra = BigTable wide-column + Dynamo replication + CQL + tunable consistency.</li><li>Riak = pure Dynamo + CRDT types.</li><li>DynamoDB = managed AP KV + optional strong consistency + transactions.</li><li>核心 trade-off: AP = always available writes, eventual consistency, 可 需要 client-side merge和read repair。 opposite of Spanner&#39;s CP+EC model。</li></ol><hr><p>下一节 → <a href="./snowflake">Snowflake</a></p>`,83)])])}const u=e(n,[["render",s]]);export{m as __pageData,u as default};
